'use strict';
let satisfactionPending=false;
let DATA, state, plans=[],draft=null,activePlan=0,resultTab='itinerary',dirty=false;
const $=s=>document.querySelector(s),clone=x=>JSON.parse(JSON.stringify(x)),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={nature:'自然山水',culture:'人文历史',food:'当地美食',resort:'住店度假'};
const fmt=n=>'¥'+Math.round(n).toLocaleString('zh-CN');
const cnDate=d=>new Date(d+'T12:00:00').toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'short'});
const addDate=(s,n)=>{let d=new Date(s+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'});
const days=()=>Math.round((new Date(state.end+'T12:00:00Z')-new Date(state.start+'T12:00:00Z'))/86400000)+1;
const city=k=>DATA.cities[k];
const modal=$('#modal');
function fresh(){let s=addDate(today(),14);return {step:1,province:'',cities:[],start:s,end:addDate(s,6),people:2,rooms:1,ages:['',''],origin:'',budget:600,longhaul:0,prefs:{start:'',pace:'',walk:'',themes:[],transport:'',lodging:'',nap:false},large:false}}
function configKey(){return JSON.stringify([state.province,state.cities,state.start,state.end,state.people,state.rooms,state.ages,state.origin,state.budget,state.longhaul,state.prefs])}
function save(){try{localStorage.setItem('wayfree-pages-trip-v1',JSON.stringify({state,plans,draft,activePlan,dirty,version:1}));}catch{toast('浏览器未允许保存；请先导出行程。')}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function sourceLink(url,label='查看来源'){return url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:''}
function mapLink(name,k){return 'https://uri.amap.com/search?keyword='+encodeURIComponent(name==='酒店'?city(k).name+' 酒店':name)+'&city='+encodeURIComponent(city(k).name)+'&view=map'}
function photo(src,alt,cls='',loading=true){return src?`<img class="${cls}" src="${esc(src)}" alt="${esc(alt)}" ${loading?'loading="lazy"':''} onerror="this.hidden=true;this.parentElement.classList.add('photo-failed')">`:`<div class="blank-image">${esc(alt)}</div>`}
function transfer(a,b){return DATA.transfers[a+'-'+b]||DATA.transfers[b+'-'+a]||null}
function transferInfo(a,b){let t=transfer(a,b);if(!t)return '';let text=state.prefs.transport==='rail'?t.rail:t.drive;if(state.prefs.transport==='rail'&&!DATA.transfers[a+'-'+b]&&text.includes('→'))text=text.replace(/^.*?，/,city(a).name+' → '+city(b).name+'，');return text}
function metricId(a){return a&&/^([a-z]+)-[0-5]$/.test(a.id)?a.id:'custom'}
function emitMetric(payload){return WayfreeMetrics.record(payload)}
function analyticsState(){if(!state.analytics)state.analytics={generations:0,edits:0,satisfied:false};return state.analytics}
function choicesMetric(){let b=state.budget,ages=state.ages.filter(x=>x!=='').map(x=>+x<40?'under40':+x<50?'40-49':+x<60?'50-59':+x<70?'60-69':+x<80?'70-79':'80+');return {province:state.province,cities:state.cities,start:state.prefs.start,pace:state.prefs.pace,walk:state.prefs.walk,transport:state.prefs.transport,themes:state.prefs.themes,budget:b<=300?'150-300':b<=500?'301-500':b<=800?'501-800':b<=1200?'801-1200':b<=2000?'1201-2000':'2001+',party:state.people===1?'1':state.people===2?'2':state.people<=4?'3-4':state.people<=8?'5-8':'9-12',ages,nap:state.prefs.nap,lodging:state.prefs.lodging||'any',month:+state.start.slice(5,7)}}
function recordEdit(type,change){analyticsState().edits++;emitMetric({type,change})}
function feedbackPanel(){let a=analyticsState();return `<section class="panel feedback-panel"><h3>这份行程，合心意了吗？</h3><p class="small">本轮已生成 ${a.generations} 次，手动调整 ${a.edits} 次。</p><button class="btn primary small-btn" data-action="satisfied" ${a.satisfied?'disabled':''}>${a.satisfied?'已反馈满意，谢谢':'这份行程满意了'}</button><p class="source-note" style="margin:12px 0 0">当前先在本浏览器累计选项与操作次数，不代表全站统计。未点击不会被算作满意。</p></section>`}
function stepper(){return `<ol class="steps" aria-label="规划进度">${['选省份','选城市','出行信息','聊聊偏好','我的行程'].map((x,i)=>`<li class="${state.step===i+1?'current':state.step>i+1?'done':''}" ${state.step===i+1?'aria-current="step"':''}><span class="step-num">${state.step>i+1?'✓':i+1}</span><span>${x}</span></li>`).join('')}</ol>`}
function action(summary,next='下一步',allow=true){return `<div class="action-bar"><div class="summary">${summary}</div><div class="button-row">${state.step>1?'<button class="btn" data-action="back">上一步</button>':''}<button class="btn primary" data-action="next" ${allow?'':'disabled'}>${next}</button></div></div>`}
function render(scroll=false){document.body.classList.toggle('large',!!state.large);$('#font-toggle').setAttribute('aria-pressed',!!state.large);$('#font-toggle').textContent=state.large?'标准字号':'大字模式';$('#app').innerHTML=`<div class="shell">${stepper()}${state.step===1||state.step===5?'<div class="ai-notice">本网站内容由 AI 整理生成，可能存在错误或过时信息。请在预订及出发前核查价格、开放时间、票务和评价。</div>':''}${[null,provincePage,cityPage,infoPage,quizPage,resultPage][state.step]()}</div>`;save();if(scroll)window.scrollTo({top:0,behavior:'smooth'})}
function provincePage(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">Wayfree</div><h1>下一站，<br>去喜欢的地方。</h1><p>不管想多看几个景点，还是住下来度个假。<br>选一选，让旅程合自己的心意。</p></div><div class="hero-image">${photo('assets/guilin.jpg','广西漓江山水','',false)}<span class="photo-caption">广西 · 漓江</span></div></section><div class="section-heading"><div><h2>这一次，想去哪里？</h2><p>先选一个省份，再自由组合城市。</p></div><span class="small">三种风景，随你出发</span></div><div class="province-grid">${DATA.provinces.map(p=>`<button class="province-card ${state.province===p.id?'selected':''}" data-action="province" data-id="${p.id}" aria-pressed="${state.province===p.id}">${photo(p.image,p.name+'目的地风景','',false)}<div class="province-info"><div class="province-top"><h3>${p.name} <span class="en">${p.en}</span></h3><span class="checkmark">✓</span></div><p>${p.line}</p>${p.cities.map(k=>`<span class="pill">${city(k).name}</span>`).join('')}</div></button>`).join('')}</div>${action(state.province?'已选择 '+DATA.provinces.find(x=>x.id===state.province).name:'选好后，我们再来挑城市','选择城市',!!state.province)}`}
function cityPage(){let p=DATA.provinces.find(x=>x.id===state.province);return `<div class="intro"><div class="eyebrow">${p.en} / ${p.name}</div><h1>哪些城市，让你心动？</h1><p>可以多选。选中后可调整先后顺序；也可以只住一座城。填写偏好后，我们还会给出目的地匹配建议。</p></div><div class="city-grid">${p.cities.map(k=>{let c=city(k),i=state.cities.indexOf(k);return `<article class="city-card ${i>=0?'selected':''}"><button class="city-select" data-action="city" data-id="${k}" aria-pressed="${i>=0}"><div class="citytop"><h3>${c.name}</h3><span class="checkmark">✓</span></div><p>${c.tagline}</p><div>${c.tags.map(t=>`<span class="pill">${labels[t]}</span>`).join('')}</div></button><div class="city-meta"><div>常见适游季节：${c.season}</div><div class="small">规划起点约 ${fmt(c.min)}/人/天，非实时报价</div></div>${i>=0?`<div class="rank-box"><span>行程第 ${i+1} 站</span><div><button class="icon-btn" data-action="city-up" data-id="${k}" ${i===0?'disabled':''} aria-label="${c.name}提前">提前</button> <button class="icon-btn" data-action="city-down" data-id="${k}" ${i===state.cities.length-1?'disabled':''}>延后</button></div></div>`:''}</article>`}).join('')}</div>${state.cities.length?`<div class="route-box"><div class="switch-row"><strong>当前路线</strong><button class="text-btn" data-action="optimize">帮我减少折返</button></div><div class="route-stops">${state.cities.map((k,i)=>`<div class="route-stop">${i?'<i class="route-sep"></i>':''}<span>${city(k).name}</span></div>`).join('')}</div>${state.cities.length>1?'<p class="small" style="margin:12px 0 0">换城会占用半天或一整天；不强求把一个省一次走完。</p>':''}</div>`:''}${action(`已选 ${state.cities.length} 座城市`,'填写出行信息',state.cities.length>0)}`}
function infoPage(){return `<div class="intro"><div class="eyebrow">THE LITTLE DETAILS</div><h1>什么时候，和谁出发？</h1><p>预算按每天每人填写。年龄可分别填写，用来提醒可能适用的票务优惠，不替任何人决定旅行节奏。</p></div><div class="info-grid"><div><section class="panel"><h3>出行安排</h3><div class="form-grid"><label class="field">出发日期<input type="date" id="start" value="${state.start}" min="${today()}" required></label><label class="field">返程日期<input type="date" id="end" value="${state.end}" min="${state.start}" required></label><label class="field">出行人数<input id="people" type="number" min="1" max="12" value="${state.people}" inputmode="numeric"></label><label class="field">每晚需要几间房<input id="rooms" type="number" min="1" max="12" value="${state.rooms}" inputmode="numeric"><small>默认两人一间，可自行调整</small></label><label class="field wide">从哪里出发？（选填）<input id="origin" value="${esc(state.origin)}" placeholder="例如：北京"><small>用于显示出发与返程提醒，具体航班与车次需在平台查询。</small></label></div><div id="date-error"></div><div class="note" id="duration-note">${days()} 天 ${Math.max(0,days()-1)} 晚 · ${state.cities.map(k=>city(k).name).join('、')}</div></section><section class="panel"><h3>同行人的年龄 <span class="small">选填，可跳过</span></h3><div class="ages" id="age-fields">${ageInputs()}</div><p class="small">年龄不自动决定景点多少或步行强度。优惠年龄、证件和水上项目限制按各景区规则核对。</p></section></div><div><section class="panel"><h3>每天每人，准备花多少？</h3><div class="budget-number" id="budget-label">${fmt(state.budget)} <small>/ 人 / 天</small></div><label class="field"><input id="budget-range" aria-label="每天每人预算滑块" type="range" min="150" max="3000" step="50" value="${state.budget}"></label><div class="preset-row">${[300,500,800,1200].map(n=>`<button data-action="budget" data-id="${n}">${fmt(n)}</button>`).join('')}</div><label class="field">自定义预算（元）<input id="budget" type="number" min="150" max="10000" step="50" value="${state.budget}"></label><p class="small">包含目的地内的住宿、餐饮、景点、市内交通、所选城市间交通和少量机动金。购物、个人消费不计入。</p><label class="field">往返出发地的大交通预留（元 / 人，选填）<input id="longhaul" type="number" min="0" max="100000" value="${state.longhaul}" inputmode="numeric"><small>填写往返合计。填 0 时不计入预算，结果会明确标注。</small></label></section><section class="panel"><h3>预算小贴士</h3><p class="small">酒店按“每间每晚”估价，再按房间数和人数分摊。三套方案都会显示预计花费，预算不够会直接提示，不会把超支酒店当作预算内选择。</p></section></div></div>${action(`${days()} 天 · ${state.people} 人 · ${state.rooms} 间房`,'聊聊旅行偏好')}`}
function ageInputs(){return Array.from({length:state.people},(_,i)=>`<label class="field">同行人 ${i+1}<input type="number" class="age-input" data-index="${i}" min="0" max="110" value="${esc(state.ages[i]??'')}" placeholder="年龄" inputmode="numeric"></label>`).join('')}
const questions=[
['start','☀','早上，你更想怎么开始？',[['late','睡到自然醒','约10点再出门，早餐不赶时间'],['normal','正常起床出发','约9点出门，按平常节奏'],['early','早点出门也愿意','约7:30出门，想抓住清晨时光']]],
['pace','◷','一天安排多少，最舒服？',[['light','少而精','通常一天1个主要安排'],['balanced','刚刚好','通常一天2个主要安排'],['full','充实一些','体力和时间允许时安排2–3个']]],
['walk','♧','走路、台阶，你能接受多少？',[['low','少走路，少台阶','优先平缓短线；不默认连续步行'],['medium','适量步行没问题','可以有园区步行和少量坡路'],['high','徒步爬坡也喜欢','愿意考虑台阶、山路和较长路线']]],
['themes','♡','什么最值得花时间？（可多选）',[['nature','自然山水','湖海、山林、田园与风景'],['culture','人文历史','博物馆、古镇、建筑与寺院'],['food','当地美食','地方菜、街巷与烟火气'],['resort','住店度假','酒店或民宿都能成为旅程的一部分']]],
['lodging','⌂','住在哪里，更合你的心意？',[['hotel','酒店','偏好标准化客房、完整配套与酒店服务'],['homestay','特色民宿 / 客栈','喜欢院落、田园、在地设计，愿意核对接驳与设施'],['any','都可以，合适最重要','一起比较位置、特色、服务和预算']]],
['transport','▱','目的地之间，怎么走更合心意？',[['rail','高铁＋当地打车','少操心长途驾驶'],['car','自己开车 / 租车','更自由，接受停车和驾驶'],['charter','包车，司机接送','少换乘；费用按整车分摊']]]
];
function quizPage(){return `<div class="quiz"><div class="intro"><div class="eyebrow">A TRIP THAT FEELS LIKE YOU</div><h1>旅行，按你的方式来。</h1><p>没有标准答案，也没有按年龄预设的偏好。告诉我们喜欢什么，就按什么安排。</p></div>${questions.map(([key,icon,title,opts])=>`<section class="quiz-section"><div class="quiz-question"><span class="q-symbol">${icon}</span><h3>${title}</h3></div><div class="options ${opts.length===4?'four':''}" role="group" aria-label="${title}">${opts.map(([v,t,s])=>{let on=key==='themes'?state.prefs.themes.includes(v):state.prefs[key]===v;return `<button class="option ${on?'selected':''}" data-action="pref" data-key="${key}" data-id="${v}" aria-pressed="${on}"><strong>${t}</strong><small>${s}</small></button>`}).join('')}</div></section>`).join('')}<section class="panel"><label class="checkline"><input id="nap" type="checkbox" ${state.prefs.nap?'checked':''}><span>每天尽量留出午休 / 回酒店休息时间</span></label><p class="small">勾选后会缩减当天可安排时段。换城和整日游可能无法回酒店，会单独提示。</p></section><div id="quiz-error"></div>${action('生成后还能删减、替换、换天和混搭','生成三套行程',questions.every(([k])=>k==='themes'?state.prefs.themes.length:!!state.prefs[k]))}</div>`}
function readInfo(){for(let k of ['start','end','origin'])if($('#'+k))state[k]=$('#'+k).value;for(let k of ['people','rooms','budget','longhaul'])if($('#'+k))state[k]=Number($('#'+k).value);document.querySelectorAll('.age-input').forEach(e=>state.ages[+e.dataset.index]=e.value);state.ages=state.ages.slice(0,state.people)}
function validInfo(){if(!state.start||!state.end||!Number.isFinite(days())||days()<1)return '请检查出发和返程日期。';if(state.start<today())return '请选择今天或以后的出发日期。';if(days()>30)return '目前最长支持30天的行程，请缩短日期范围。';if(state.people<1||state.people>12||!Number.isInteger(state.people))return '出行人数请填1–12位。';if(state.rooms<1||state.rooms>state.people||!Number.isInteger(state.rooms))return '房间数需在1间和出行人数之间。';if(state.people>state.rooms*2)return '当前按每间最多两人估算，请增加房间数；加床和亲子房需另向酒店确认。';if(state.budget<150||state.budget>10000)return '每天每人预算请填150–10,000元。';if(state.longhaul<0||!Number.isFinite(state.longhaul))return '大交通预算需填0或正数。';if(state.ages.some(a=>a!==''&&(+a<0||+a>110)))return '年龄请填0–110岁，或留空。';if(days()<state.cities.length*2)return `选了${state.cities.length}座城市，建议至少${state.cities.length*2}天，才能留出换城和游览时间。请延长日期或减少城市。`;return ''}
function matchScore(k){let c=city(k),score=state.prefs.themes.filter(t=>c.tags.includes(t)).length*3;if(state.budget>=c.min)score+=2;let m=+state.start.slice(5,7);if(k==='banna'&&[11,12,1,2,3].includes(m))score+=3;if(k==='beihai'&&[4,5,9,10].includes(m))score+=2;if(['kunming','dali','lijiang'].includes(k)&&[3,4,5,9,10,11].includes(m))score+=2;return score}
function matchingStays(k){let all=city(k).hotels.map((h,i)=>({h,i}));let pref=state.prefs.lodging||'any';let matched=pref==='any'?all:all.filter(x=>(x.h.stayType||'hotel')===pref);return matched.length?matched:all}
function hotelEstimate(h){return (h.lo+h.hi)/2}
function selectHotel(k,variant){let pool=matchingStays(k),target=state.budget*(state.prefs.themes.includes('resort')?.60:.40)*state.people/state.rooms;let affordable=pool.filter(x=>(x.h.lo+x.h.hi)/2<=target);if(variant===2)return pool.reduce((best,x)=>hotelEstimate(x.h)<hotelEstimate(best.h)?x:best,pool[0]).i;if(!affordable.length)return pool.reduce((best,x)=>hotelEstimate(x.h)<hotelEstimate(best.h)?x:best,pool[0]).i;let goal=target*(variant===1?1:.82);return affordable.sort((a,b)=>Math.abs((a.h.lo+a.h.hi)/2-goal)-Math.abs((b.h.lo+b.h.hi)/2-goal))[0].i}
function lodgingSection(d,di){let c=city(d.city),pool=matchingStays(d.city),pref=state.prefs.lodging||'any',target=state.budget*(state.prefs.themes.includes('resort')?.60:.40)*state.people/state.rooms;let ordered=pool.sort((a,b)=>Math.abs((a.h.lo+a.h.hi)/2-target)-Math.abs((b.h.lo+b.h.hi)/2-target)).map(x=>x.i);let top=[d.hotel,...ordered.filter(i=>i!==d.hotel)].slice(0,3),more=c.hotels.map((_,i)=>i).filter(i=>!top.includes(i));return `<div class="hotel-title"><h4>今晚住哪里？${pref==='homestay'?'优先看特色民宿':pref==='hotel'?'优先看酒店':'酒店与特色民宿一起看'}</h4><span class="small">${state.rooms}间房 · 住到${addDate(d.date,1).slice(5).replace('-','/')}</span></div><p class="small" style="margin:10px 0 0">本城收录 ${c.hotels.length} 家住宿；先展示 ${top.length} 家，仍可自由更换。${pref==='homestay'&&pool.length<3?'本城目前仅核验到 '+pool.length+' 家民宿，可展开更多备选比较其他类型；类型会分别标明。':''}</p><div class="hotel-grid">${top.map(i=>hotelCard(c.hotels[i],d,di,i)).join('')}</div>${more.length?`<details class="more-stays"><summary>再看 ${more.length} 家住宿（含其他类型）</summary><div class="hotel-grid">${more.map(i=>hotelCard(c.hotels[i],d,di,i)).join('')}</div></details>`:''}`}

function generate(){let metrics=analyticsState();if(metrics.satisfied){state.analytics={generations:0,edits:0,satisfied:false};metrics=state.analytics}metrics.generations++;emitMetric({type:'generate',choices:choicesMetric()});let count=days(),base=Math.floor(count/state.cities.length),extra=count%state.cities.length;let allocation=state.cities.map((k,i)=>({k,n:base+(i<extra?1:0)}));plans=[0,1,2].map(v=>{let rows=[],day=0;allocation.forEach(({k,n},ci)=>{let used=new Set(),acts=city(k).acts.map((a,i)=>({...clone(a),id:k+'-'+i,city:k}));for(let j=0;j<n;j++,day++){let tr=j===0&&ci>0?transfer(state.cities[ci-1],k):null;let first=day===0,last=day===count-1;let maxWalk={low:1,medium:2,high:3}[state.prefs.walk];let available=first||last?3:tr?Math.max(0,8-tr.hours):state.prefs.nap?6:8;let desired={light:1,balanced:2,full:3}[state.prefs.pace];if(first||last||tr)desired=Math.min(desired,1);let date=addDate(state.start,day);let rank=acts.filter(a=>a.walk<=maxWalk&&!used.has(a.id)&&(a.tag!=='resort'||state.prefs.themes.includes('resort'))&&(v!==2||a.cost<=Math.min(150,state.budget*.25))&&(!a.closedWeekday||new Date(date+'T12:00:00').getDay()!==a.closedWeekday)).map(a=>({...a,score:(state.prefs.themes.includes(a.tag)?12:0)+(v===0? (a.tag===state.prefs.themes[0]?5:0):v===1?(a.tag===state.prefs.themes[state.prefs.themes.length-1]?8:2):(150-a.cost)/30)+(a.tag==='resort'&&state.prefs.themes.includes('resort')?3:0)-(used.has(a.id)?30:0)+((+a.id.split('-').pop()+v*2)%6)/5})).sort((a,b)=>b.score-a.score);desired=Math.min(desired,Math.max(1,Math.ceil(rank.length/(n-j))));let selected=[],time=0;for(let a of rank){if(selected.length>=desired)break;let extra=selected.length?.75:0;if(time+a.hours+extra<=available){selected.push(a);used.add(a.id);time+=a.hours+extra}}if(!selected.length&&available>=2)selected=[{id:k+'-free-'+day,city:k,name:'自由安排，按当天心情出发',tag:'resort',hours:2,walk:0,cost:0,detail:'可以休息，或从备选里挑一个附近的安排。',booking:'无需预约；如另选收费项目请核对。',highlight:'自己决定时间怎么花',skip:'当天不想出门就留在酒店',area:'酒店',image:city(k).image,reviews:[]}];rows.push({city:k,date:addDate(state.start,day),acts:selected,hotel:selectHotel(k,v),override:null,transferFrom:tr?state.cities[ci-1]:null,first,last});}});return {name:['心愿优先','另一种体验','精打细算'][v],desc:[`优先${state.prefs.themes.map(t=>labels[t]).join('、')}，按你选的出门时间和活动强度安排。`,'保留相同节奏和步行限制，换一组体验；预算允许时更重住宿。','优先较低住宿成本和免费、低票价体验，保留喜欢的旅行主题。'][v],days:rows}});economizePlans();activePlan=0;draft=clone(plans[0]);dirty=false;state.generatedKey=configKey();state.step=5;resultTab='itinerary';render(true)}
// Compare complete trips using the same lodging, meals and ticket estimates as the UI.
// Candidates preserve the selected pace, walking limits, themes and accommodation type.
function economizePlans(){if(plans.length!==3)return;let candidates=[plans[2],plans[0],plans[1]].map(p=>{let candidate=clone(p);candidate.days.forEach(d=>{d.hotel=selectHotel(d.city,2);d.override=null});return candidate});let best=candidates.reduce((a,b)=>calc(b).total<calc(a).total?b:a);best.name='精打细算';best.desc='按统一口径比较整套住宿、门票与餐饮费用，选择较省的组合；保留你的节奏和住宿类型偏好。手动修改后费用会重新计算。';plans[2]=best}
window.WayfreeFeedbackContext=()=>({version:'2026.11.21-budget-fix',step:state?.step,cities:state?.cities?.map(k=>city(k).name)||[],days:state?days():0,people:state?.people,rooms:state?.rooms,budget:state?.budget,prefs:state?clone(state.prefs):{},planEstimates:plans.map(p=>({name:p.name,daily:Math.round(calc(p).daily),total:Math.round(calc(p).total)})),activePlan:draft?.name,edited:dirty});
function calc(plan=draft){let acc=0,attractions=0,food=0,local=0,cross=0;let p=state.people,r=state.rooms;for(let d of plan.days){if(!d.last){let h=city(d.city).hotels[d.hotel];acc+=(d.override??(h.lo+h.hi)/2)*r}food+=Math.max(state.prefs.themes.includes('food')?130:90,d.acts.filter(a=>a.tag==='food').reduce((s,a)=>s+a.cost,0)+40)*p;attractions+=d.acts.filter(a=>a.tag!=='food').reduce((s,a)=>s+a.cost,0)*p;local+=(state.prefs.transport==='charter'?600*Math.ceil(p/4):state.prefs.transport==='car'?220*Math.ceil(p/4):70*p)*(d.transferFrom?.5:1);if(d.transferFrom){let tr=transfer(d.transferFrom,d.city);cross+=state.prefs.transport==='rail'?tr.railCost*p:state.prefs.transport==='charter'?tr.carCost*2.0*Math.ceil(p/4):tr.carCost*Math.ceil(p/4)}}let buffer=(food+attractions+local+cross)*.10,long=state.longhaul*p,total=acc+food+attractions+local+cross+buffer+long;return {acc,attractions,food,local,cross,buffer,long,total,daily:total/p/plan.days.length,target:state.budget*p*plan.days.length}}
function timeStr(n){let hour=Math.floor(n),min=Math.round((n-hour)*60);if(min===60){hour++;min=0}return String(hour).padStart(2,'0')+':'+String(min).padStart(2,'0')}
function timeline(d){let t=d.first?14:d.transferFrom?Math.max({late:10,normal:9,early:7.5}[state.prefs.start],8)+transfer(d.transferFrom,d.city).hours:({late:10,normal:9,early:7.5}[state.prefs.start]);let rows=[],napDone=false;for(let a of d.acts){if(t>=12&&t<14){t=state.prefs.nap?14.5:13.5;napDone=!!state.prefs.nap}let start=t,end=t+a.hours;rows.push({start,end,a});t=end+.75}return {rows,end:t-.75,napDone}}
function dayWarnings(d){let w=[],tl=timeline(d);if(tl.end>19)w.push('活动结束偏晚，建议删减一项');if(d.last&&tl.end>14)w.push('返程当天较满，请按实际车次删减');if(d.acts.some(a=>a.walk>{low:1,medium:2,high:3}[state.prefs.walk]))w.push('含超过所选步行强度的安排');if(d.acts.some(a=>a.closedWeekday&&new Date(d.date+'T12:00:00').getDay()===a.closedWeekday))w.push('该安排可能遇固定闭馆日，请替换或换天');if(d.acts.some(a=>a.name.includes('金顶'))&&d.acts.length>1)w.push('金顶通常需整天，建议保留这一项即可');if(d.acts.some(a=>a.name.includes('漓江游船')))w.push('游船抵达阳朔方向，当天返回桂林需另留时间');if(state.prefs.nap&&(d.acts.some(a=>a.hours>=5)||d.transferFrom))w.push('整日游或换城日不保证回酒店午休');if(d.transferFrom&&transfer(d.transferFrom,d.city).hours>=6)w.push('长距离换城日，建议不再加景点');if(d.acts.length>{light:1,balanced:2,full:3}[state.prefs.pace])w.push('安排数量超过偏好，确认体力与时间');return w}
function resultPage(){if(!draft)return '<div class="empty">还没有生成行程，请先完成前面的选择。</div>';let c=calc();return `<section class="result-hero"><div><div class="eyebrow" style="color:#c4d8c9;margin-bottom:10px">MAKE ROOM FOR WHAT YOU LOVE</div><h1>${state.cities.map(k=>city(k).name).join(' · ')}，这样玩。</h1><p>${cnDate(state.start)} — ${cnDate(state.end)} · ${days()}天${days()-1}晚 · ${state.people}人 ${state.rooms}间房</p></div><div class="button-row"><button class="btn" data-action="recommend">目的地匹配</button><button class="btn" data-action="edit-settings">修改条件</button><button class="btn" data-action="export">导出行程</button></div></section><div class="note">先选一套做主行程，再打开“混搭备选”添加喜欢的安排。每天可删除、替换、调序和换天；修改会保存在本设备浏览器中。</div><div class="plan-options">${plans.map((p,i)=>{let t=calc(p);return `<article class="plan-option ${activePlan===i?'active':''}"><div class="overline">方案 ${i+1}${i===0?' · 按偏好推荐':''}</div><h3>${p.name}${activePlan===i?' <span class="selected-label">当前主方案</span>':''}</h3><p>${p.desc}</p><div class="plan-price">${fmt(t.daily)} <small>/ 人 / 天</small></div><div class="small ${t.daily>state.budget?'over-budget':''}">${t.daily>state.budget?'超目标预算 '+fmt(t.daily-state.budget)+'/人/天':'预计在目标预算内'} · 原始方案估算</div><div class="spacer"></div><button class="btn ${activePlan===i?'subtle':'primary'} small-btn" data-action="use-plan" data-id="${i}">${activePlan===i?(dirty?'已调整 · 可恢复原方案':'已用作主行程'):'用这套做主行程'}</button></article>`}).join('')}</div><div class="tabs" role="tablist">${[['itinerary','每日行程'],['mix','混搭备选'],['tips','温馨提示'],['booking','订票与出行']].map(([k,t])=>`<button role="tab" aria-selected="${resultTab===k}" class="${resultTab===k?'active':''}" data-action="tab" data-id="${k}">${t}</button>`).join('')}</div><div class="result-layout"><div>${resultTab==='itinerary'?itinerary():resultTab==='mix'?mixPage():resultTab==='tips'?tipsPage():bookingPage()}</div><aside class="sidebar">${budgetPanel(c)}${feedbackPanel()}<div class="panel"><h3>这次的旅行偏好</h3><p class="small">${{late:'约10点出门',normal:'约9点出门',early:'约7:30出门'}[state.prefs.start]} · ${{light:'一天1个主要安排',balanced:'一天2个主要安排',full:'时间允许时2–3个安排'}[state.prefs.pace]}<br>${{low:'少走路、少台阶',medium:'可适量步行',high:'可徒步爬坡'}[state.prefs.walk]}${state.prefs.nap?' · 尽量留午休':''}</p>${state.prefs.themes.map(t=>`<span class="pill">${labels[t]}</span>`).join('')}<p class="small">住宿：${{hotel:'酒店',homestay:'特色民宿 / 客栈',any:'酒店与民宿均可'}[state.prefs.lodging||'any']}</p><p class="small" style="margin-top:12px">年龄：${state.ages.some(x=>x!=='')?state.ages.filter(x=>x!=='').map(x=>x+'岁').join('、'):'未填写'}<br>节奏完全依据本人选择。</p></div><div class="panel"><h3>旅程目录</h3><nav class="day-nav">${draft.days.map((d,i)=>`<a href="#day-${i}" data-action="jump" data-id="${i}">第${i+1}天 · ${city(d.city).name}${d.transferFrom?' · 换城':''}</a>`).join('')}</nav></div></aside></div><div class="print-only">${tipsPage()}${bookingPage()}</div>`}
function budgetPanel(c){return `<section class="panel"><h3>这份行程，预计花费</h3><div class="budget-number" style="font-size:2rem">${fmt(c.total)}</div><p class="small">${state.people}人全程合计 · ${state.rooms}间房</p>${[['住宿',c.acc],['餐饮',c.food],['景点与体验',c.attractions],['市内交通',c.local],['所选城市间交通',c.cross],['机动金',c.buffer],['往返出发地',c.long]].map(([k,v])=>`<div class="metric"><span>${k}</span><span>${v||k!=='往返出发地'?fmt(v):'未计入'}</span></div>`).join('')}<div class="metric total"><span>平均每天每人</span><span class="${c.daily>state.budget?'over-budget':''}">${fmt(c.daily)}</span></div><div class="budget-bar"><div style="width:${Math.min(100,c.daily/state.budget*100)}%"></div></div><p class="small ${c.daily>state.budget?'over-budget':''}">${c.daily>state.budget?'高于目标约 '+fmt(c.daily-state.budget)+'/人/天，可换较低价酒店或删减体验。':'目标 '+fmt(state.budget)+'/人/天，预留空间约 '+fmt(state.budget-c.daily)+'/人/天。'}</p><details><summary>怎么算的？</summary><p>酒店默认采用区间中位数 × 房间数。可为每晚填写实际房价。餐饮每人每天${state.prefs.themes.includes('food')?130:90}元起；美食安排计入餐饮，避免重复计算。交通为规划预留，不是平台报价。</p><p>租车按每4人1辆预留租金、油费停车等；包车约600元/辆/天，跨城按路程另计。车型、异地还车费等以报价为准。机动金为目的地内非住宿支出的10%。</p><p>${state.longhaul?'往返出发地按填写金额计入。':'未填往返大交通，当前总额不含出发地往返机票/车票。'}购物、个人消费不含；未自动扣除年龄相关票价优惠。</p></details></section>`}
function itinerary(){return `<div class="section-heading"><div><h2>你的每日行程${dirty?' · 已调整':''}</h2><p class="small">时间为建议，可随实际到达时间调整。图片点击可查看详情。</p></div></div>${draft.days.map(dayCard).join('')}`}
function dayCard(d,i){let tl=timeline(d),warnings=dayWarnings(d),c=city(d.city);return `<article class="day-card" id="day-${i}"><header class="day-head"><div><div class="day-date">${cnDate(d.date)}</div><h3>第 ${i+1} 天 · ${c.name}</h3></div><span class="day-badge">${d.first?'抵达日':d.last?'返程日':d.transferFrom?'换城日':d.acts.length?'按心意出发':'自由安排'}</span></header><div class="day-content">${d.first?`<div class="transfer-box"><strong>${esc(state.origin||'出发地')} → ${c.name}</strong><br>按实际航班或车次抵达；当天暂从14:00安排，晚到请删去活动。<br>${c.station}；${c.airport}。入住前可向酒店确认寄存行李。</div>`:''}${d.transferFrom?`<div class="transfer-box"><strong>${city(d.transferFrom).name} → ${c.name}</strong><br>${transferInfo(d.transferFrom,d.city)}<br><span class="small">时间为区间估计，含两端接驳需多留缓冲。${state.prefs.transport==='rail'?'按12306确认具体车站和车次。':'不含堵车与服务区休息；连续驾驶请合理休息。'}</span></div>`:''}<div class="route-box" style="margin:0 0 18px;padding:14px 16px"><strong style="font-size:.9rem">当天交通顺序</strong><p class="small" style="margin:6px 0">${d.first?'抵达车站 / 机场':d.transferFrom?'抵达本城':('酒店 · '+c.hotels[d.hotel].area)} ${d.acts.length?' / '+d.acts.map(a=>esc(a.area)).join(' / '):''} / ${d.last?'返程车站 / 机场':'酒店'}</p><p class="small" style="margin:0">${{rail:'市内以打车或公共交通接驳',car:'自驾按上述地点串联，提前查停车点',charter:'包车可把这些停靠点提前发给司机'}[state.prefs.transport]}；活动间暂留45分钟，长距离请按地图实际车程调整。</p></div>${warnings.length?`<div class="validation-list">${warnings.map(w=>`<span>${w}</span>`).join('')}</div>`:''}${!d.acts.length?'<div class="empty">这一天留给交通和休息。也可以添加一个附近的安排。</div>':''}${tl.rows.map(({a,start,end},ai)=>activityCard(a,i,ai,start,end)).join('')}${state.prefs.nap?`<p class="small" style="margin-top:15px">午休偏好：${d.acts.some(a=>a.hours>=5)||d.transferFrom?'当天可能在外，优先找就近室内休息点。':'为午餐与休息留出时段；活动之间可回酒店，需另留车程。'}</p>`:''}<div class="button-row" style="margin-top:16px"><button class="btn small-btn subtle" data-action="add" data-day="${i}">添加安排</button><button class="text-btn" data-action="custom" data-day="${i}">自己写一项</button>${i>0&&draft.days[i-1].city===d.city?`<button class="text-btn" data-action="day-swap" data-day="${i}" data-other="${i-1}">与前一天交换活动</button>`:''}</div><section class="day-food"><strong>这一站，吃点当地的</strong><p>${c.food.join(' · ')}</p><p>可参考：${c.restaurant}</p><p>如果人多：${c.backup}</p><a href="${mapLink(c.restaurant,d.city)}" target="_blank" rel="noopener">地图找餐厅与附近备选</a><span class="small"> · 营业、分店及排队请当天确认</span></section>${d.last?`<div class="transfer-box"><strong>${c.name} → ${esc(state.origin||'返程目的地')}</strong><br>按实际返程票调整。建议国内航班预留机场办理时间，高铁另留进站和市内接驳时间；当天不推荐安排不可退的长时体验。<br>返程日不计住宿。</div>`:`${lodgingSection(d,i)}<label class="field small" style="margin-top:15px">查到今晚实际房价？填这里（元 / 间 / 晚）<input class="night-price" data-day="${i}" type="number" min="0" max="100000" value="${d.override??''}" placeholder="留空使用所选酒店估价，非实时房价"><small>只有当前这一晚采用此价格，含税、早餐等按实际订单核对。</small></label>`}</div></article>`}
function activityImage(a,di){let day=draft.days[di];return a.area==='酒店'?city(day.city).hotels[day.hotel].image:(a.image||city(day.city).image)}
function activityCard(a,di,ai,start,end){let d=draft.days[di];return `<section class="activity"><div data-action="activity-detail" data-day="${di}" data-act="${ai}" role="button" tabindex="0" aria-label="查看${esc(a.name)}详情">${photo(activityImage(a,di),a.area==='酒店'?'所选酒店实景':a.image?a.name+'实景':city(d.city).name+'参考风景')}<span class="image-credit">${a.area==='酒店'?'所选酒店':a.image?'地点实景':'目的地参考图'}</span></div><div><div class="time">${timeStr(start)}–${timeStr(end)} · 约${a.hours}小时</div><h4>${esc(a.name)}</h4><p>${esc(a.detail)}</p><div class="activity-links"><button class="text-btn" style="padding:0;font-size:inherit" data-action="activity-detail" data-day="${di}" data-act="${ai}">亮点、取舍与订票</button><a href="${mapLink(a.area,d.city)}" target="_blank" rel="noopener">地图查路线</a></div><div class="activity-edit"><button class="icon-btn" data-action="replace" data-day="${di}" data-act="${ai}">替换</button><button class="icon-btn" data-action="act-up" data-day="${di}" data-act="${ai}" ${ai===0?'disabled':''}>提前</button><button class="icon-btn" data-action="act-down" data-day="${di}" data-act="${ai}" ${ai===d.acts.length-1?'disabled':''}>延后</button><select class="move-select" data-day="${di}" data-act="${ai}" aria-label="把${esc(a.name)}移到另一天"><option value="">移到另一天</option>${draft.days.map((day,j)=>day.city===d.city&&j!==di?`<option value="${j}">第${j+1}天 ${cnDate(day.date)}</option>`:'').join('')}</select><button class="icon-btn danger-btn" data-action="delete-act" data-day="${di}" data-act="${ai}">删除</button></div></div></section>`}
function hotelCard(h,d,di,hi){let target=state.budget*(state.prefs.themes.includes('resort')?.60:.40)*state.people/state.rooms;return `<article class="hotel-card ${d.hotel===hi?'chosen':''}"><div class="hotel-photo" role="button" tabindex="0" data-action="hotel-detail" data-city="${d.city}" data-id="${hi}" aria-label="查看${esc(h.name)}图片与评价">${photo(h.image,h.name+'实景')}<span>${h.image?'住宿实景 · 查看详情':'图片待补 · 查看资料'}</span></div><div class="hotel-info"><span class="pill stay-type">${esc(h.typeLabel||'酒店')}</span><h5>${esc(h.name)}</h5><p>${h.area} · ${h.why}</p><div class="hotel-price">${fmt(h.lo)}–${h.hi.toLocaleString()} <small>/间/晚</small></div><p class="small">规划区间，非所选日期报价${h.lo>target?' · 高于住宿分配':''}</p><p class="hotel-review-mini">${h.reviews?.length?'反馈重点：'+esc(h.reviews[0].short):'近期差评证据不足，需打开点评核对'}</p><div class="hotel-actions"><button class="btn small-btn ${d.hotel===hi?'subtle':'primary'}" data-action="hotel-pick" data-day="${di}" data-id="${hi}">${d.hotel===hi?'✓ 今晚选择':'选这家'}</button><button class="btn small-btn" data-action="hotel-detail" data-city="${d.city}" data-id="${hi}">图片 / 差评</button></div></div></article>`}
function mixPage(){return `<div class="intro"><h2>以一套为主，喜欢的再加进来。</h2><p>这里汇集三套方案和同城备选。只添加到同一城市，避免把一天的交通改乱。添加后会重新计算费用与时间。</p></div>${state.cities.map(k=>{let variants=new Map;plans.forEach((p,pi)=>p.days.filter(d=>d.city===k).forEach(d=>d.acts.forEach(a=>{if(!variants.has(a.id))variants.set(a.id,{a,from:[]});variants.get(a.id).from.push(pi+1)})));city(k).acts.forEach((a,i)=>{let id=k+'-'+i;if(!variants.has(id))variants.set(id,{a:{...a,id,city:k},from:[]})});return `<section class="panel"><h3>${city(k).name} · 备选安排</h3><div class="reference-list">${[...variants.values()].map(({a,from})=>`<div class="reference-item">${photo(a.image||city(k).image,a.name)}<div><h4>${a.name}</h4><p>${[...new Set(from)].length?'来自方案 '+[...new Set(from)].join('、'):'其他同城选择'} · 约${a.hours}小时 · ${{0:'几乎不步行',1:'轻步行',2:'适量步行 / 坡路',3:'台阶或较长路线'}[a.walk]}</p><p>${a.highlight}</p></div><div class="ref-actions"><select data-mix-id="${a.id}" aria-label="为${esc(a.name)}选择日期">${draft.days.map((d,i)=>d.city===k?`<option value="${i}">第${i+1}天 · ${d.date.slice(5)}</option>`:'').join('')}</select><button class="btn small-btn subtle" data-action="mix-add" data-city="${k}" data-id="${a.id}">加入主行程</button></div></div>`).join('')}</div></section>`}).join('')}`}
function seasonal(k){let m=+(draft?.days.find(day=>day.city===k)?.date||state.start).slice(5,7),winter=[12,1,2].includes(m),summer=[6,7,8].includes(m);if(k==='banna')return winter?'冬季参考：白天轻便衣物，早晚薄外套；防晒帽、舒适鞋和防蚊用品。':summer?'夏季参考：透气速干衣、防晒衣、遮阳帽，备雨具；中午可选室内或酒店。':'参考：轻便衣物＋薄外套，防晒、防蚊、备雨具。';if(['kunming','dali','lijiang'].includes(k))return winter?'冬季参考：长袖叠穿、保暖防风外套和长裤；湖边风大，日夜温差明显。':summer?'夏季参考：短袖或薄长袖＋轻外套，雨具、防晒帽、防滑鞋。':'春秋参考：薄长袖＋可脱的外套，长裤、防晒帽；湖边加一层防风。';if(k==='emei')return winter?'冬季参考：山脚保暖外套；高山区另带厚保暖层、防风防水层与防滑鞋，关注冰雪交通。':'山脚可按季节轻便穿着；上高山区另备保暖防风层、雨具和防滑鞋，温差不可忽略。';return winter?'冬季参考：保暖内搭＋防风外套、长裤和防滑鞋，注意湿冷和江海边风。':summer?'夏季参考：透气衣物、防晒帽、雨具与防滑鞋，备替换上衣；避开酷热时段持续步行。':'春秋参考：长短袖分层、薄外套与舒适鞋，雨具随身。'}
function tipsPage(){let ages=state.ages.filter(x=>x!==''),month=+state.start.slice(5,7);return `<div class="intro"><h2>出发前，心里有个底。</h2><p>${state.start}至${state.end}的季节性参考，不是实时天气预报。出发前3–7天再查预报与景区公告。</p></div>${[1,2,5,7,8,10].includes(month)?'<div class="note warning" style="margin-bottom:20px">日期可能接近节假日、寒暑假或热门旅行季。请按当年放假安排核对，优先确认酒店取消规则、余票与价格。</div>':''}<div class="tip-grid">${state.cities.map(k=>`<article class="tips-card"><h3>${city(k).name}</h3><h4>穿什么、带什么</h4><p>${seasonal(k)}</p><p>${city(k).climate}</p><h4>这一站最值得保留</h4><p>${city(k).acts.filter(a=>state.prefs.themes.includes(a.tag)).slice(0,2).map(a=>a.name+'：'+a.highlight).join('；')||city(k).acts[0].highlight}</p><h4>时间不够，可以舍弃</h4><p>${city(k).acts.slice(0,3).map(a=>a.skip).join('；')}。取舍依个人兴趣，不代表景点好坏排名。</p><h4>反馈与运营提醒</h4>${city(k).tips?.map(t=>`<div class="review-box"><p>${t.text}</p><div class="source-link">${sourceLink(t.url,t.label||'游客反馈 / 官方来源')}</div><p class="source-note">${t.date||'页面样本，具体体验日期未核验'} · 整理于2026-11-21</p></div>`).join('')||'<p>景区开放、排队和临时项目可能变化，订票前查看官方公告和最新评价。</p>'}<div class="links-inline"><a href="https://www.weather.com.cn/" target="_blank" rel="noopener">查天气预报</a><a href="${mapLink(city(k).name+' 景点',k)}" target="_blank" rel="noopener">查当地地图</a></div></article>`).join('')}</div><section class="panel" style="margin-top:22px"><h3>关于同行年龄与优惠</h3><p>${ages.length?'本次填写年龄：'+ages.map(x=>esc(x)+'岁').join('、')+'。':'尚未填写年龄。'}不默认所有景区60岁或65岁免费；需要核对证件、适用人群、观光车和索道是否优惠。水上体验或高山区项目可能有额外限制，订票前按同行人情况确认。</p>${state.cities.includes('chengdu')&&ages.some(x=>+x>=60)?'<p class="note">本次有60岁及以上同行人：熊猫基地当前官方政策为凭有效身份证件免票免预约，出发前复核；其他景区分别确认。</p>':''}${state.cities.includes('yangshuo')&&ages.some(x=>+x>=70)?'<p class="note warning">本次有70岁及以上同行人：遇龙河部分竹筏航段有年龄限制，本行程只默认安排岸边，购筏票前请按航段规则确认。</p>':''}<p class="source-note">游客差评为样本提示，不是总体统计；相反体验可能同时存在。优先看近期、相同房型和相同季节的评价。</p></section>`}
function bookingPage(){return `<div class="intro"><h2>从预订到出发，一步一步来。</h2><p>这里提供查询入口和操作顺序；网页不会代下单，也不显示实时库存。</p></div><section class="panel"><h3>先确定大交通，再锁定住宿</h3><p class="note">按常规15天（含当天）预售期，${state.start}出发的铁路车票可重点从${addDate(state.start,-14)}起关注；具体起售时刻按车站与公告。</p>${[['先查出发与返程','从'+(state.origin||'你的出发地')+'到'+city(state.cities[0]).name+'，以及从'+city(state.cities.at(-1)).name+'返回。比较一进一出，避免无谓折返。'],['确认所选城市之间的交通','高铁用12306按日期查询，注意同一城市不同车站。当前常规预售期为15天（含当天），具体起售时间按车站；远期日期先查线路，放票后再买。'],['酒店先看房型与取消条款','每晚先展示三家，还可展开更多酒店或民宿。确认双床/大床、早餐人数、楼栋、是否可取消、噪音敏感需求及到景点的实际距离；连住可统一选同一家以减少搬行李。'],['景区按官方要求预约','点击每日景点详情看预约提示。门票、观光车、索道、游船常是不同产品；不要只看一张低价票就以为都包含。'],['出发前再次核对','确认天气、闭馆/检修、船班或索道状态，保存订单和证件。偏远路段提前沟通接送位置。']].map(([h,p],i)=>`<div class="booking-step"><span class="booking-num">${i+1}</span><div><strong>${h}</strong><p>${p}</p></div></div>`).join('')}<div class="button-row"><a class="btn primary" href="https://www.12306.cn/" target="_blank" rel="noopener">12306 查高铁</a><a class="btn" href="https://www.ctrip.com/" target="_blank" rel="noopener">携程查机票与酒店</a></div><p class="source-note" style="margin-top:15px">预售期来源：${sourceLink('https://help.12306.cn/cms/answer/h5/001531826595438842083440b580b2e0','中国铁路12306')}；以最新公告为准。</p></section><section class="panel"><h3>城市之间怎么走</h3>${state.cities.length<2?'<p>这次只住一座城市，不安排跨城交通。</p>':state.cities.slice(1).map((k,i)=>`<details open><summary>${city(state.cities[i]).name} 与 ${city(k).name}</summary><p>${transfer(state.cities[i],k).rail}</p><p>${transfer(state.cities[i],k).drive}</p><p>所列时间与费用为规划参考，实际车次、票价和路况请查询。反向行驶时车站顺序相反。</p></details>`).join('')}</section><section class="panel"><h3>到站以后，先认清位置</h3>${state.cities.map(k=>`<details><summary>${city(k).name}</summary><p>车站：${city(k).station}<br>机场：${city(k).airport}</p><p>先在地图中设置酒店，再选择打车、公交或自驾路线。${k==='yangshuo'?'阳朔高铁站位于兴坪附近，不能把“出高铁站”当作“到阳朔西街”。':''}${k==='emei'?'“峨眉山站”与“峨眉站”不同，请对照订单。':''}</p><a href="${mapLink(city(k).station.split(' / ')[0],k)}" target="_blank" rel="noopener">在地图中查询</a></details>`).join('')}</section>`}
function showModal(title,body){$('#modal-body').innerHTML=`<header class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭">关闭</button></header><div class="modal-content">${body}</div>`;if(!modal.open)modal.showModal()}
function reviewsHTML(items,unknown='尚未找到可核验的具体近期差评。'){if(!items?.length)return `<div class="review-box"><p>${unknown}</p><p class="source-note">预订前打开评价页，重点筛选近半年、相同房型的隔音、卫生、位置与设施反馈。没有收录差评不等于没有问题。</p></div>`;return items.map(r=>`<div class="review-box"><strong>${esc(r.short)}</strong><p>${esc(r.text)}</p><p class="source-link">${sourceLink(r.url,r.label||'查看住客反馈原页')}</p><p class="source-note">${esc(r.date||'具体入住日期未核验')} · 页面整理于2026-11-21。样本反馈，非总体结论。</p></div>`).join('')}
function hotelDetail(k,i){let h=city(k).hotels[i],imgs=h.images?.length?h.images:[h.image].filter(Boolean);showModal(h.name,`<div class="gallery">${imgs.map(x=>photo(x,h.name+'实景')).join('')}</div><p class="image-credit">住宿公开实景图，房型与当前实景请以预订页面为准。${h.imagePage?sourceLink(h.imagePage,'图片来源'):sourceLink(h.url,'酒店资料')}</p><h3>这是什么类型的住宿？</h3><p>${esc(h.typeLabel||'酒店')} · ${h.area}</p><h3>特色与适合的玩法</h3><p>${h.why}。</p>${h.notes?`<div class="note"><strong>下单前先问清</strong><p style="margin:6px 0 0">${esc(h.notes)}</p></div>`:''}<h3>规划房价</h3><p>${fmt(h.lo)}–${fmt(h.hi)} / 间 / 晚。此为规划区间，不是${state.start}至${state.end}的实时报价；节假日可能超出区间。</p><h3>重要差评与需要确认的点</h3>${reviewsHTML(h.reviews)}<p class="note">预订时可问：安静房是否可保证？有无装修或活动噪音？从下车点到客房需走多远？是否有电梯？同一酒店不同楼栋、朝向和房型的体验可能不同。</p><div class="button-row modal-actions"><a class="btn primary" href="${esc(h.url)}" target="_blank" rel="noopener">${h.url==='https://hotels.ctrip.com/'?'携程搜索酒店全名':'查看酒店 / 预订入口'}</a><a class="btn" href="${esc(h.ctrip)}" target="_blank" rel="noopener">携程预订这家酒店</a><a class="btn" href="${mapLink(h.name,k)}" target="_blank" rel="noopener">地图查位置</a>${h.ctrip?`<a class="btn" href="${h.ctrip}" target="_blank" rel="noopener">查看全部住客点评</a>`:''}</div><p class="small" style="margin-top:16px">查询时请重新输入入住与退房日期、${state.people}人、${state.rooms}间房。此入口不会自动完成预订。</p>`)}
function activityDetail(di,ai){let a=draft.days[di].acts[ai],k=draft.days[di].city;showModal(a.name,`<div class="gallery">${photo(activityImage(a,di),a.area==='酒店'?'所选酒店实景':a.image?a.name+'实景':city(k).name+'目的地参考风景')}</div><p class="image-credit">${a.image?'对应地点实景':'目的地参考风景，具体景点照片待补充'}${a.imagePage?' · '+sourceLink(a.imagePage,'图片来源'):''}</p><p class="small">照片用于理解地点，不代表所选日期的天气、季节或实时景象。</p><h3>亮点在哪里</h3><p>${a.highlight}</p><h3>累不累？安排多久？</h3><p>约${a.hours}小时；${{0:'以坐着体验或短距离走动为主，上下车/船仍可能有台阶。',1:'平缓或短线步行较多，可按体力缩短。',2:'园区步行或山路坡道，需安排休息。',3:'包含连续台阶、爬坡或较长路线，请按实际体力评估。'}[a.walk]}</p><h3>时间不够，可省哪些</h3><p>${a.skip}</p><h3>票好买吗？要不要提前订？</h3><p>${a.booking}</p><p class="small">未接入所选日期的实时余票，不能保证能买到。旺季优先核对预约；免费景区也可能需要实名预约。</p><h3>游客反馈与实际提醒</h3>${reviewsHTML(a.reviews,'尚未收录可核验的该项目具体游客差评，请查看近期评价，并结合上面的官方预约和路线提醒。')}<div class="button-row modal-actions"><a class="btn primary" href="${mapLink(a.area,k)}" target="_blank" rel="noopener">地图查路线</a>${a.source?`<a class="btn" href="${a.source}" target="_blank" rel="noopener">官方信息与预约说明</a>`:`<a class="btn" href="https://www.ctrip.com/" target="_blank" rel="noopener">查询景点产品</a>`}</div>`)}
function picker(di,replace=-1){let k=draft.days[di].city;showModal(replace<0?'为这一天添加安排':'换一种安排',`<p class="small">只显示${city(k).name}的选择。时间与步行强度不合偏好时仍可自己选择，加入后会提示。</p><div class="reference-list">${city(k).acts.map((a,i)=>`<article class="reference-item">${photo(a.image||city(k).image,a.name)}<div><h4>${a.name}</h4><p>约${a.hours}小时 · ${labels[a.tag]} · ${fmt(a.cost)}/人预留</p><p>${a.highlight}</p></div><button class="btn small-btn" data-action="picker-add" data-day="${di}" data-act="${replace}" data-city="${k}" data-id="${i}">选这一项</button></article>`).join('')}</div>`)}
function changed(message){dirty=true;save();render();if(message)toast(message)}
function getAct(k,id){let i=+id.split('-').at(-1);let a=city(k).acts[i];if(a)return {...clone(a),id,city:k};for(let p of plans)for(let d of p.days){let x=d.acts.find(a=>a.id===id);if(x)return clone(x)}return null}
function addAct(di,a,replace=-1){let d=draft.days[di];if(d.acts.some((x,i)=>x.id===a.id&&i!==replace)){toast('这一天已经有这个安排了');return}recordEdit(replace>=0?'activity_replace':'activity_add',{city:d.city,from:replace>=0?metricId(d.acts[replace]):'none',to:metricId(a)});if(replace>=0)d.acts[replace]=a;else d.acts.push(a);modal.close();changed('已更新安排，时间和预算已重新计算')}
function recommendModal(){let p=DATA.provinces.find(x=>x.id===state.province);showModal('按偏好看看哪里更适合',`<p>这是基于兴趣、季节与预算的规则匹配，供比较选择。</p>${[...p.cities].sort((a,b)=>matchScore(b)-matchScore(a)).map(k=>`<section class="panel"><h3>${city(k).name}${state.cities.includes(k)?' · 已选':''}</h3><p>${city(k).tags.filter(t=>state.prefs.themes.includes(t)).map(t=>labels[t]).join('、')||'可补充其他体验'} · ${city(k).season}</p><p class="small">${state.budget>=city(k).min?'预算起点较匹配':'预算偏紧，可减少付费项目或换较低价住宿'}</p><button class="btn small-btn" data-action="recommend-pick" data-id="${k}">${state.cities.includes(k)?'从行程移除':'加入所选城市'}</button></section>`).join('')}`)}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b||b.disabled)return;let act=b.dataset.action,k=b.dataset.id,di=+b.dataset.day,ai=+b.dataset.act;switch(act){case'province':if(state.province!==k){state.province=k;state.cities=[]}render();break;case'city':state.cities=state.cities.includes(k)?state.cities.filter(x=>x!==k):[...state.cities,k];render();break;case'city-up':case'city-down':{let i=state.cities.indexOf(k),j=i+(act==='city-up'?-1:1);[state.cities[i],state.cities[j]]=[state.cities[j],state.cities[i]];render();break}case'optimize':{let seq=state.province==='yunnan'?(state.cities.includes('banna')?['lijiang','dali','kunming','banna']:['kunming','dali','lijiang']):DATA.provinces.find(p=>p.id===state.province).cities;state.cities.sort((a,b)=>seq.indexOf(a)-seq.indexOf(b));render();toast('已按相邻路线调整，可继续自己排序');break}case'back':if(state.step===3)readInfo();state.step--;render(true);break;case'next':if(state.step===3){readInfo();let error=validInfo();if(error){$('#date-error').innerHTML=`<div class="error" role="alert">${error}</div>`;$('#date-error').scrollIntoView({behavior:'smooth',block:'center'});break}}if(state.step===4){if(draft&&dirty&&!confirm('重新生成会覆盖当前行程的手动调整。是否继续？'))break;if(!questions.every(([key])=>key==='themes'?state.prefs.themes.length:state.prefs[key])){toast('请先完成偏好选择');break}let error=validInfo();if(error){toast(error);state.step=3;render(true);break}generate();break}state.step++;render(true);break;case'budget':state.budget=+k;$('#budget').value=k;$('#budget-range').value=k;$('#budget-label').innerHTML=fmt(+k)+' <small>/ 人 / 天</small>';save();break;case'pref':{let key=b.dataset.key;if(key==='themes')state.prefs.themes=state.prefs.themes.includes(k)?state.prefs.themes.filter(x=>x!==k):[...state.prefs.themes,k];else state.prefs[key]=k;let y=window.scrollY;render();window.scrollTo(0,y);break}case'use-plan':if(dirty&&!confirm('重新选择主方案会替换当前修改。是否继续？'))break;analyticsState().edits++;emitMetric({type:'plan_select',change:{from:activePlan,to:+k}});activePlan=+k;draft=clone(plans[activePlan]);dirty=false;render();toast('已切换主行程');break;case'tab':resultTab=k;render();break;case'jump':resultTab='itinerary';render();setTimeout(()=>$('#day-'+k)?.scrollIntoView({behavior:'smooth',block:'start'}),30);break;case'edit-settings':state.step=3;render(true);break;case'hotel-pick':if(draft.days[di].hotel===+k)break;recordEdit('hotel_change',{city:draft.days[di].city,from:draft.days[di].hotel,to:+k});draft.days[di].hotel=+k;draft.days[di].override=null;changed('已换酒店，预算已更新');break;case'hotel-detail':hotelDetail(b.dataset.city,+k);break;case'activity-detail':activityDetail(di,ai);break;case'close-modal':modal.close();break;case'delete-act':recordEdit('activity_delete',{city:draft.days[di].city,from:metricId(draft.days[di].acts[ai]),to:'none'});draft.days[di].acts.splice(ai,1);changed('已删除，可从混搭备选里重新添加');break;case'act-up':case'act-down':{let a=draft.days[di].acts,j=ai+(act==='act-up'?-1:1);[a[ai],a[j]]=[a[j],a[ai]];recordEdit('activity_reorder',{city:draft.days[di].city});changed('已调整顺序');break}case'day-swap':{recordEdit('day_swap',{city:draft.days[di].city});let j=+b.dataset.other;[draft.days[di].acts,draft.days[j].acts]=[draft.days[j].acts,draft.days[di].acts];changed('已交换活动，日期与酒店保持原安排');break}case'add':picker(di);break;case'replace':picker(di,ai);break;case'picker-add':addAct(di,{...clone(city(b.dataset.city).acts[+k]),id:b.dataset.city+'-'+k,city:b.dataset.city},ai);break;case'mix-add':{let sel=document.querySelector('[data-mix-id="'+k+'"]'),a=getAct(b.dataset.city,k);if(a)addAct(+sel.value,a);break}case'custom':showModal('自己写一个安排',`<form id="custom-form" data-day="${di}"><label class="field">安排名称<input id="custom-name" maxlength="70" required placeholder="例如：和老朋友吃饭"></label><label class="field">说明<textarea id="custom-description" maxlength="400" rows="3"></textarea></label><div class="form-grid" style="margin-top:16px"><label class="field">预计小时数<input id="custom-hours" type="number" min="0.5" max="12" step="0.5" value="2" required></label><label class="field">额外费用（元 / 人）<input id="custom-cost" type="number" min="0" max="10000" value="0" required></label></div><div class="modal-actions"><button class="btn primary" type="submit">加入这一天</button></div></form>`);break;case'export':showModal('保存和分享行程',`<p>可打印成PDF，也可以下载文字行程发给家人。网页的个人修改保存在当前设备，不会自动同步到其他人的手机。</p><div class="button-row"><button class="btn primary" data-action="print">打印 / 存为PDF</button><button class="btn" data-action="download-text">下载文字行程</button><button class="btn" data-action="copy-text">复制文字行程</button></div><p class="small" style="margin-top:18px">PDF会包含当前选择的酒店、每日活动、温馨提示及订票说明。打印面板中选择“另存为PDF”。</p>`);break;case'print':emitMetric({type:'export'});modal.close();resultTab='itinerary';render();window.print();break;case'download-text':{emitMetric({type:'export'});let blob=new Blob([exportText()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='我的旅行行程-'+state.start+'.txt';a.click();URL.revokeObjectURL(url);toast('已下载文字行程');break}case'copy-text':emitMetric({type:'export'});navigator.clipboard.writeText(exportText()).then(()=>toast('已复制行程')).catch(()=>toast('复制未获允许，请下载文字行程'));break;case'satisfied':{let stats=analyticsState();if(stats.satisfied||satisfactionPending)break;satisfactionPending=true;b.disabled=true;emitMetric({type:'satisfied',effort:{generations:Math.min(100,Math.max(1,stats.generations)),edits:Math.min(500,stats.edits)}}).then(ok=>{satisfactionPending=false;if(ok){stats.satisfied=true;save();render();toast('已在本机记下满意反馈，谢谢！')}else{b.disabled=false;toast('暂未记入统计，请稍后再试')}});break}case'recommend':recommendModal();break;case'recommend-pick':if(state.cities.includes(k)&&state.cities.length===1){toast('至少保留一座城市');break}state.cities=state.cities.includes(k)?state.cities.filter(x=>x!==k):[...state.cities,k];modal.close();state.step=3;render(true);toast('目的地已更新，请重新生成行程');break}});
document.addEventListener('change',e=>{let el=e.target;if(el.classList.contains('move-select')&&el.value!==''){let from=+el.dataset.day,to=+el.value,i=+el.dataset.act,a=draft.days[from].acts[i];if(draft.days[to].acts.some(x=>x.id===a.id)){toast('目标日期已经有这个安排');el.value='';return}recordEdit('activity_move',{city:draft.days[from].city});draft.days[from].acts.splice(i,1);draft.days[to].acts.push(a);changed('已移到第'+(to+1)+'天');return}if(el.classList.contains('night-price')){let value=el.value===''?null:+el.value;if(value!==null&&(value<0||value>100000)){toast('房价请填写0–100,000元');return}recordEdit('price_adjust',{city:draft.days[+el.dataset.day].city});draft.days[+el.dataset.day].override=value;changed('已采用填写房价');return}if(el.id==='nap'){state.prefs.nap=el.checked;save();return}if(el.classList.contains('age-input')){state.ages[+el.dataset.index]=el.value;save();return}if(['start','end','people','rooms','origin','budget','longhaul'].includes(el.id)){if(el.id==='people'){let n=Math.min(12,Math.max(1,Math.floor(+el.value||1)));state.people=n;state.rooms=Math.ceil(n/2);$('#rooms').value=state.rooms;state.ages=Array.from({length:n},(_,i)=>state.ages[i]??'');$('#age-fields').innerHTML=ageInputs();el.value=n}readInfo();if($('#duration-note'))$('#duration-note').textContent=(Number.isFinite(days())&&days()>0?days()+' 天 '+(days()-1)+' 晚':'请检查日期')+' · '+state.people+'人';if($('#end'))$('#end').min=state.start;save()}});
document.addEventListener('input',e=>{if(['budget-range','budget'].includes(e.target.id)){let n=+e.target.value;state.budget=n;if(e.target.id==='budget-range')$('#budget').value=n;else $('#budget-range').value=Math.min(3000,n);$('#budget-label').innerHTML=fmt(n)+' <small>/ 人 / 天</small>';save()}});
document.addEventListener('submit',e=>{if(e.target.id==='custom-form'){e.preventDefault();let form=e.target,di=+form.dataset.day,name=$('#custom-name').value.trim();if(!name)return;addAct(di,{id:'custom-'+Date.now(),city:draft.days[di].city,name,detail:$('#custom-description').value.trim(),hours:+$('#custom-hours').value,cost:+$('#custom-cost').value,tag:'custom',walk:0,booking:'自行确认预约和开放情况。',highlight:'你自己选择的安排',skip:'可按当天情况调整',area:name,image:'',reviews:[]})}});
modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][data-action]')){e.preventDefault();e.target.click()}});
$('#font-toggle').onclick=()=>{state.large=!state.large;render()};$('#resume').onclick=()=>{if(draft&&state.generatedKey!==configKey()){state.step=4;render(true);toast('出行条件已改变，请重新生成行程');return}if(draft){state.step=5;resultTab='itinerary';render(true)}else toast('完成选择后，这里会保存你的行程')};$('#home-link').onclick=e=>{e.preventDefault();state.step=1;render(true)};
function exportText(){let c=calc(),lines=['我的旅行行程',state.start+' 至 '+state.end+' · '+state.people+'人 · '+state.rooms+'间房',state.cities.map(k=>city(k).name).join(' / '),'预计总计 '+fmt(c.total)+'，平均 '+fmt(c.daily)+'/人/天',state.longhaul?'已包含填写的往返出发地交通预留':'未包含往返出发地机票/车票','本内容由AI整理生成，可能出错或过时，请在预订与出发前核查。','价格为规划估算；资料整理于2026-11-21。'];draft.days.forEach((d,i)=>{lines.push('\n第'+(i+1)+'天 '+cnDate(d.date)+' '+city(d.city).name);if(d.transferFrom)lines.push('换城：'+transferInfo(d.transferFrom,d.city));if(d.first)lines.push('抵达日：按实际航班/车次调整，暂从14:00安排。');timeline(d).rows.forEach(({a,start,end})=>{lines.push(timeStr(start)+'–'+timeStr(end)+' '+a.name,a.detail,'亮点：'+a.highlight,'可省：'+a.skip,'预约：'+a.booking,'路线：'+mapLink(a.area,d.city));a.reviews?.forEach(r=>lines.push('反馈样本：'+r.text+' '+r.url))});lines.push('必吃：'+city(d.city).food.join('、'),'用餐参考：'+city(d.city).restaurant,'人多时：'+city(d.city).backup);if(!d.last){let h=city(d.city).hotels[d.hotel];lines.push('今晚住宿：'+h.name+'（'+h.area+'）','每间每晚：'+(d.override!==null?fmt(d.override):fmt(h.lo)+'–'+fmt(h.hi)+'，规划估算'),h.url);h.reviews?.forEach(r=>lines.push('住客反馈样本：'+r.text+' '+r.url))}else lines.push('返程日：依实际车次预留接驳和办理时间。');dayWarnings(d).forEach(w=>lines.push('提醒：'+w))});lines.push('\n穿衣与出行提示');state.cities.forEach(k=>{lines.push(city(k).name+'：'+seasonal(k));city(k).tips?.forEach(t=>lines.push(t.text+' '+t.url))});lines.push('季节建议并非实时天气预报，出发前3–7天再查。','车票： https://www.12306.cn/','常规预售期15天（含当天），以车站公告为准。','游客反馈是样本，不是总体结论。近期实际情况请再次核对。');return lines.join('\n')}
(async()=>{try{DATA=await(await fetch('data.json')).json();let stored;try{stored=JSON.parse(localStorage.getItem('wayfree-pages-trip-v1'))}catch{}state=stored?.version===1?stored.state:fresh();if(stored?.version===1){plans=stored.plans||[];draft=stored.draft;activePlan=stored.activePlan||0;dirty=!!stored.dirty}if(!('lodging' in state.prefs)){state.prefs.lodging='any';if(draft&&state.step===5)state.generatedKey=configKey()}if(plans.length===3){economizePlans();if(activePlan===2&&!dirty)draft=clone(plans[2])}if(state.step===5&&!draft)state.step=1;if(draft&&!state.analytics)state.analytics={generations:1,edits:0,satisfied:false};render();emitMetric({type:'visit'})}catch(e){$('#app').innerHTML='<div class="page-error"><h1>资料加载遇到问题</h1><p>请刷新页面重试。</p><button class="btn" onclick="location.reload()">重新加载</button></div>';console.error(e)}})();
